CREATE TYPE public.app_role AS ENUM ('admin','student');
CREATE TYPE public.material_type AS ENUM ('PDF','Video','Article');
CREATE TABLE public.profiles (id uuid PRIMARY KEY, name text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 80), email text NOT NULL, preferences jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "profiles self select" ON public.profiles FOR SELECT TO authenticated USING(auth.uid()=id); CREATE POLICY "profiles self insert" ON public.profiles FOR INSERT TO authenticated WITH CHECK(auth.uid()=id); CREATE POLICY "profiles self update" ON public.profiles FOR UPDATE TO authenticated USING(auth.uid()=id) WITH CHECK(auth.uid()=id);
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL DEFAULT 'student', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY "roles self select" ON public.user_roles FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, category text NOT NULL, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subjects TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.subjects TO authenticated; GRANT ALL ON public.subjects TO service_role; ALTER TABLE public.subjects ENABLE ROW LEVEL SECURITY; CREATE POLICY "subjects public read" ON public.subjects FOR SELECT TO anon,authenticated USING(true); CREATE POLICY "subjects admin write" ON public.subjects FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.enrollments (user_id uuid NOT NULL, subject_id uuid NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,subject_id));
GRANT SELECT,INSERT,DELETE ON public.enrollments TO authenticated; GRANT ALL ON public.enrollments TO service_role; ALTER TABLE public.enrollments ENABLE ROW LEVEL SECURITY; CREATE POLICY "enrollments self" ON public.enrollments FOR ALL TO authenticated USING(auth.uid()=user_id OR public.has_role(auth.uid(),'admin')) WITH CHECK(auth.uid()=user_id OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(char_length(title) BETWEEN 3 AND 160), description text NOT NULL CHECK(char_length(description) BETWEEN 20 AND 1200), subject_id uuid NOT NULL REFERENCES public.subjects(id) ON DELETE RESTRICT, type public.material_type NOT NULL, url text NOT NULL, tags text[] NOT NULL DEFAULT '{}', uploaded_by uuid, average_rating numeric(3,2) NOT NULL DEFAULT 0, rating_count integer NOT NULL DEFAULT 0, view_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.materials TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.materials TO authenticated; GRANT ALL ON public.materials TO service_role; ALTER TABLE public.materials ENABLE ROW LEVEL SECURITY; CREATE POLICY "materials public read" ON public.materials FOR SELECT TO anon,authenticated USING(true); CREATE POLICY "materials admin write" ON public.materials FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin')); CREATE INDEX materials_title_idx ON public.materials(title); CREATE INDEX materials_subject_idx ON public.materials(subject_id); CREATE INDEX materials_tags_idx ON public.materials USING gin(tags); CREATE INDEX materials_rating_idx ON public.materials(average_rating DESC);
CREATE TABLE public.ratings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, material_id uuid NOT NULL REFERENCES public.materials(id) ON DELETE CASCADE, score integer NOT NULL CHECK(score BETWEEN 1 AND 5), review text CHECK(char_length(review)<=1000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,material_id));
GRANT SELECT ON public.ratings TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.ratings TO authenticated; GRANT ALL ON public.ratings TO service_role; ALTER TABLE public.ratings ENABLE ROW LEVEL SECURITY; CREATE POLICY "ratings public read" ON public.ratings FOR SELECT TO anon,authenticated USING(true); CREATE POLICY "ratings self insert" ON public.ratings FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id); CREATE POLICY "ratings self update" ON public.ratings FOR UPDATE TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id); CREATE POLICY "ratings self delete" ON public.ratings FOR DELETE TO authenticated USING(auth.uid()=user_id);
CREATE TABLE public.search_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, query text NOT NULL, result_count integer NOT NULL DEFAULT 0, subject_id uuid REFERENCES public.subjects(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.search_logs TO authenticated; GRANT ALL ON public.search_logs TO service_role; ALTER TABLE public.search_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY "searches read" ON public.search_logs FOR SELECT TO authenticated USING(auth.uid()=user_id OR public.has_role(auth.uid(),'admin')); CREATE POLICY "searches insert" ON public.search_logs FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id); CREATE INDEX search_logs_user_time_idx ON public.search_logs(user_id,created_at DESC);
CREATE TABLE public.material_views (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, material_id uuid NOT NULL REFERENCES public.materials(id) ON DELETE CASCADE, viewed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.material_views TO authenticated; GRANT ALL ON public.material_views TO service_role; ALTER TABLE public.material_views ENABLE ROW LEVEL SECURITY; CREATE POLICY "views read" ON public.material_views FOR SELECT TO authenticated USING(auth.uid()=user_id OR public.has_role(auth.uid(),'admin')); CREATE POLICY "views insert" ON public.material_views FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id); CREATE INDEX views_user_time_idx ON public.material_views(user_id,viewed_at DESC);
CREATE TABLE public.recommendations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, material_id uuid NOT NULL REFERENCES public.materials(id) ON DELETE CASCADE, score numeric(6,5) NOT NULL CHECK(score BETWEEN 0 AND 1), reason text NOT NULL, generated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,material_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.recommendations TO authenticated; GRANT ALL ON public.recommendations TO service_role; ALTER TABLE public.recommendations ENABLE ROW LEVEL SECURITY; CREATE POLICY "recommendations read" ON public.recommendations FOR SELECT TO authenticated USING(auth.uid()=user_id OR public.has_role(auth.uid(),'admin')); CREATE POLICY "recommendations self write" ON public.recommendations FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id); CREATE INDEX recommendations_user_score_idx ON public.recommendations(user_id,score DESC);
CREATE OR REPLACE FUNCTION public.refresh_material_rating() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; BEGIN mid:=COALESCE(NEW.material_id,OLD.material_id); UPDATE public.materials SET average_rating=COALESCE((SELECT avg(score) FROM public.ratings WHERE material_id=mid),0),rating_count=(SELECT count(*) FROM public.ratings WHERE material_id=mid),updated_at=now() WHERE id=mid; RETURN COALESCE(NEW,OLD); END $$; CREATE TRIGGER ratings_refresh AFTER INSERT OR UPDATE OR DELETE ON public.ratings FOR EACH ROW EXECUTE FUNCTION public.refresh_material_rating();
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name,email) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'name',split_part(NEW.email,'@',1)),COALESCE(NEW.email,'')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'student'); RETURN NEW; END $$; CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();